ST.xhtml:p:
Rtring_move(CLK := g_bAvoidCylAndAxisMoveControlM);
IF Rtring_move.Q THEN
  g_bAvoidCylAndAxisMoveControlM := FALSE;
  dAbsPosition := M.PARAMETER_I[309];
  bAbsExecute := TRUE;
END_IF;





RTring_Enable(CLK := bAbsExecute OR g_bAntiRejection6AbsExecute);

IF RTring_Enable.Q THEN
  nAbsState := 1;
  g_boAntiRejection6AbsDone := FALSE;
  g_bAntiRejection6AbsDone := FALSE;
  IF bAbsExecute THEN
    dTargetPos := dAbsPosition;
    dTargetVel := 0.0;
    IF g_bPowerOffMoveToTargetPosSetSpeedFlag THEN
      dTargetVel := g_dPowerOffMoveToTargetPosSpeed;
    END_IF;
  ELSE
    dTargetPos := g_fARAbsPosition6;
    dTargetVel := g_fARAbsVelocity6;
  END_IF;
  IF dTargetVel = 0.0 THEN
    dTargetVel := dAutoVelocity;
  END_IF;
  bAbsExecute := FALSE;
  g_bAntiRejection6AbsExecute := FALSE;
END_IF;

CASE nAbsState OF
  0:
    nAbsState := 0;
  1:
    g_AntiRejection6Abs.Execute := TRUE;
    g_AntiRejection6Abs.Velocity := dTargetVel;
    g_AntiRejection6Abs.Position := dTargetPos;
    IF g_AntiRejection6Abs.Done THEN
      g_AntiRejection6Abs.Execute := FALSE;
      g_boAntiRejection6AbsDone := TRUE;
      g_bAntiRejection6AbsDone := TRUE;
      nAbsState := 0;
      M.ENABLE[309] := 0;
    END_IF;
    IF g_bPlcPauseBuffer THEN
      nAbsState := 20;
    END_IF;
    IF g_AntiRejection6Abs.CommandAborted OR g_AntiRejection6Abs.Error THEN
      g_AntiRejection6Abs.Execute := FALSE;
      nAbsState := 0;
    END_IF;
  20:
    g_AntiRejection6Abs.Execute := FALSE;
    g_AntiRejection6Stop.Execute := TRUE;
    IF g_AntiRejection6Stop.Done AND g_bPlcStartBuffer THEN
      g_AntiRejection6Stop.Execute := FALSE;
      nAbsState := 1;
    END_IF;
    IF g_AntiRejection6Stop.CommandAborted OR g_AntiRejection6Stop.Error THEN
      g_AntiRejection6Stop.Execute := FALSE;
      nAbsState := 0;
    END_IF;
END_CASE;

IF g_bPlcResetBuffer THEN
  nAbsState := 0;
  g_AntiRejection6Abs.Execute := FALSE;
  g_AntiRejection6Stop.Execute := FALSE;
END_IF;
